```js
export function normalizeTransaction(transaction) {
  const id = transaction.id;
  const account = transaction.account;
  const kind = transaction.kind;
  const amount = transaction.amount;

  if (typeof id !== 'string' || id === '' || typeof account !== 'string' || account === '' || !(kind === 'credit' || kind === 'debit')) {
    throw new TypeError(`Invalid transaction ${String(id)}`);
  }

  const amountStr = String(amount);
  const match = amountStr.match(/^(\d+)(\.(\d\d?))?$/);
  if (!match) {
    throw new TypeError(`Invalid transaction ${String(id)}`);
  }

  const dollars = match[1];
  const cents = match[3] ? match[3].padEnd(2, '0') : '00';
  const totalCents = parseInt(dollars, 10) * 100 + parseInt(cents, 10);
  if (totalCents <= 0) {
    throw new TypeError(`Invalid transaction ${String(id)}`);
  }

  return {
    id,
    account,
    cents: kind === 'credit' ? totalCents : -totalCents,
  };
